std::vector<std::unique_ptr<ChooserContextBase::Object>> GetGrantedObjects(
    const GURL& requesting_origin,
    const GURL& embedding_origin) {
  std::vector<std::unique_ptr<ChooserContextBase::Object>> results;

  // Check if origins are valid.
  if (!requesting_origin.is_valid() || !embedding_origin.is_valid()) {
    return results;
  }

  // Check if permission is granted.
  if (!CanGrantPermission(requesting_origin, embedding_origin)) {
    return results;
  }

  // Retrieve website settings.
  WebsiteSettings* settings = GetWebsiteSettings(requesting_origin);
  if (!settings) {
    return results;
  }

  // Extract and validate objects.
  for (const auto& obj : settings->GetObjects()) {
    if (obj->IsValid() && obj->IsGranted()) {
      results.push_back(std::unique_ptr<ChooserContextBase::Object>(obj->Clone()));
    }
  }

  return results;
}

